-- Carga idempotente ejecutada con un usuario que tenga activo el rol seller.
-- Fuente de las asignaciones: Practica 03/seeds/categorizacion_productos_completo.csv
-- Ejecutar desde la raiz del repositorio:
--   mysql -u <usuario_seller> -p db_test < "Practica 03/scripts/cargar_categorizacion_productos.sql"
-- Requiere SELECT, INSERT en tbc_categories y tbd_products_categories.
-- No requiere LOAD DATA LOCAL, tablas temporales ni rutinas almacenadas.

USE `db_test`;

-- Preflight: las filas devueltas deben ser (101, Alimentos y Bebidas) y
-- (102, Herramientas y Ferreteria), como en la base de referencia.
SELECT `ID`, `name`
FROM `tbc_categories`
WHERE `ID` IN (101, 102)
   OR `name` IN ('Alimentos y Bebidas', 'Herramientas y Ferretería');

-- Inserta las categorías raíz si aún no existen. Los conflictos de ID/nombre
-- generan error para evitar asociar productos a una categoría equivocada.
INSERT INTO `tbc_categories`
  (`ID`, `name`, `description`, `sup_id_category`, `status`)
SELECT 101, 'Alimentos y Bebidas',
       'Categoría raíz para productos etiquetados como Alimentos y Bebidas.',
       NULL, b'1'
FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM `tbc_categories` WHERE `ID` = 101 AND `name` = 'Alimentos y Bebidas');

INSERT INTO `tbc_categories`
  (`ID`, `name`, `description`, `sup_id_category`, `status`)
SELECT 102, 'Herramientas y Ferretería',
       'Categoría raíz para productos etiquetados como Herramientas y Ferretería.',
       NULL, b'1'
FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM `tbc_categories` WHERE `ID` = 102 AND `name` = 'Herramientas y Ferretería');

-- La carga se divide en bloques para mantener cada sentencia pequeña.
